  ('ng-x16-midas', 'Hard-Shell Backpack', 25, NULL, 12),
  ('ng-x16-midas', 'Main Body', 270, 'Reduced to zero, the armor shuts down completely and is useless.', 13),
  ('ng-uelx45-night-reaper', 'Head', 50, 'Small target: Called Shot, -4 to strike. Destroying it ends all optical and sensor enhancement and Robot Combat bonuses; underwater below 220 ft (67 m) the pilot takes 2D6 S.D.C./Hit Points per melee round and bonuses are halved.', 1),
  ('ng-uelx45-night-reaper', 'Arms (2)', 40, 'Each.', 2),
  ('ng-uelx45-night-reaper', 'Legs (2)', 70, 'Each.', 3),
