  ('ng-x67-prophet', 'Peekaboo Cameras (2, back)', 5, 'Each. Small target: Called Shot, -4 to strike.', 3),
  ('ng-x67-prophet', 'UEL Cables (2)', 6, 'Each. Small target: Called Shot, -4 to strike.', 4),
  ('ng-x67-prophet', 'Vibro-Blades (2, one each forearm)', 30, 'Each. Small target: Called Shot, -4 to strike.', 5),
