INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note) VALUES
  ('ng-x16-midas', 1, 'NG-116 Laser Cannon', '3D6+2 M.D. per single blast; 1D6x10 M.D. for a rapid pulse of three near-simultaneous blasts', 1, '4,000 ft (1,219 m)', 'Each single shot or pulse counts as one melee attack', 'Effectively unlimited on nuclear and Solid Oxide suits; 40 blasts per charge on the electric battery version', NULL, 'Assault and anti-personnel, secondarily anti-aircraft and defense. A new, experimental turret mount on the back: it turns 360 degrees with a 45 degree up and down arc, so it can engage flyers, aircraft and missile volleys, leaving the pilot''s hands free. The gun lifts out to be fired by hand as a heavy energy rifle, cabled to the suit for power, and is pushed back into the turret afterward. Simple gun cameras face front on the cannon and rear on the turret.'),
  ('ng-x16-midas', 2, 'Forearm Ion Blaster and Vibro-Blade (1, right)', 'Ion blaster 3D6 M.D. per blast; Vibro-Blade 1D6 M.D.', 1, 'Ion blaster 800 ft (244 m); Vibro-Blade arm''s reach, about 5 ft (1.5 m)', 'Each blast counts as one melee attack', 'Effectively unlimited on nuclear and Solid Oxide suits; 30 blasts per charge on the electric battery version', NULL, 'Anti-personnel, secondarily defense. A short-range point-and-shoot blaster with a Vibro-Blade for close combat in a hidden housing beneath it.'),
  ('ng-x16-midas', 3, 'Forearm Flamethrower (1, left)', '3D6 M.D. to the target and everyone within 10 ft (3 m), double to beings vulnerable to fire; 1D6 M.D. on diesel or gasoline', 1, '80 ft (24.4 m)', 'Each burst counts as one melee attack', '9 bursts from an 18 gallon (68 liter) reserve of military napalm', NULL, 'Anti-structure and anti-personnel, secondarily anti-monster. A small removable unit for clearing bunkers and dug-in positions and against fuel tanks, infantry and fire-shy monsters. Its tank sits under the laser turret and feeds the arm by a 3 M.D.C. hose behind the arm, with a spare hose kept on the tank; waterproof valves seal it off underwater. Anyone caught by it in a bunker, cave or unsealed vehicle without their own air saves vs poison or passes out for 1D4 melee rounds.'),
  ('ng-x16-midas', 4, 'NG-MML16-4 Mini-Missile Launchers (2, chest)', 'By missile; usually plasma (1D6x10 M.D.) or armor piercing/heat (1D4x10 M.D.), but any type fits', 1, 'One mile (1.6 km)', 'One at a time or volleys of 2 or 4', '4 total, two per launcher; reloading all four by hand from missiles carried along takes one melee round', NULL, 'Anti-aircraft, anti-missile and assault, secondarily anti-armor and defense. A small dose of explosive firepower.'),
  ('ng-x16-midas', 5, 'Vibro-Blade Pole Arm (handheld)', '4D6 M.D. with the blade of the halberd or battle axe; 2D6 M.D. with the blunt end; the suit''s Robot P.S. 30 is included', 1, 'Melee; the halberd reaches 12 ft (3.6 m), the battle axe 8 ft (2.4 m)', 'Equal to the pilot''s combined hand to hand attacks', 'Unlimited', '+1 to parry and disarm', 'Assault and close combat, secondarily defense. An oversized halberd or battle axe, silver plated against the supernatural, held to the suit''s back by magnets when not in use. Sold alone for 215,000 credits (gear row ng-x16-midas-giant-vibro-blade).'),
  ('ng-uelx45-night-reaper', 1, 'Vibro-Scythe (handheld)', '3D6 M.D. with the suit''s Robot P.S. 22; the scythe alone does 2D6 M.D.', 1, 'Melee; strikes up to 4 ft (1.2 m) beyond arm''s reach, 7 ft (2.1 m) overall', 'Equal to the pilot''s combined hand to hand attacks', 'One hour per standard E-Clip; unlimited plugged into a UEL', NULL, 'Assault and close combat, secondarily defense. A pole arm, best used two-handed and silver plated against the supernatural. A new weapon NG is trying out by offering it only with this suit, to be added to its Vibro-Blade line if there is demand; many owners sell or trade theirs, so resold scythes do circulate, though they are not easy to find. No separate price is printed.'),
  ('ng-gccpa-03-pit-fighter', 1, 'Fire Breath Plasma Cannon (optional; head or forearm)', '4D6 M.D. per blast as throttled; 1D4x10 M.D. if the nozzle is tightened, losing the fire-breath look', 1, '120 ft (36.6 m); triple on a forearm at the same damage', 'Single shots; each blast is one melee attack', 'Effectively unlimited', NULL, 'Anti-armor, anti-robot and anti-monster, secondarily assault. A light cannon hidden at the chin or along the jaw and deliberately opened up, so its plasma dribbles out like a dragon''s breath. 30,000 credits (gear row ng-gccpa-03-fire-breath-plasma-cannon).'),
  ('ng-gccpa-03-pit-fighter', 2, 'Eye Lasers (optional; 2)', '1D6 M.D. per single blast; 2D6 M.D. for both eyes at one target', 1, '400 ft (122 m)', 'Each single or linked blast counts as one melee attack', 'Effectively unlimited', NULL, 'Assault and defense, secondarily anti-personnel. A simple backup light laser in each eye. 15,000 credits (gear row ng-gccpa-03-eye-lasers).'),
  ('ng-gccpa-03-pit-fighter', 3, 'Laser Forearm Blaster (optional)', '3D6 M.D. per blast', 1, '1,000 ft (305 m)', 'Each blast counts as one melee attack', 'Effectively unlimited', NULL, 'Assault and defense, secondarily anti-personnel. Point and fire, on one forearm. 28,000 credits (gear row ng-gccpa-03-laser-forearm-blaster).'),
  ('ng-gccpa-03-pit-fighter', 4, 'Ion Forearm Blaster (optional)', '4D6 M.D. per blast', 1, '600 ft (183 m)', 'Each blast counts as one melee attack', 'Effectively unlimited', NULL, 'Assault and defense, secondarily anti-personnel. Point and fire, on one forearm. 32,000 credits (gear row ng-gccpa-03-ion-forearm-blaster).'),
  ('ng-gccpa-03-pit-fighter', 5, 'Plasma Forearm Blaster (optional)', '4D6 M.D. per blast', 1, '600 ft (183 m)', 'Each blast counts as one melee attack', 'Effectively unlimited', NULL, 'Assault and defense, secondarily anti-personnel. Point and fire, on one forearm. 40,000 credits (gear row ng-gccpa-03-plasma-forearm-blaster).'),
  ('ng-gccpa-03-pit-fighter', 6, 'Forearm Grenade Launcher (optional)', 'By grenade type; high explosive and plasma look best in the arena', 1, '400 ft (122 m)', 'Single shot; each grenade counts as one melee attack', 'Four grenades', NULL, 'Assault and defense, secondarily anti-personnel. Point and fire, on one forearm. 35,000 credits (gear row ng-gccpa-03-forearm-grenade-launcher).'),
  ('ng-gccpa-03-pit-fighter', 7, 'Forearm Grappling Hook (optional)', '1 M.D. when the hook or spike is fired into something; it must be pulled free to use again', 1, '30 ft (9.1 m)', 'Each use counts as one melee attack', '48 ft (14.6 m) of cable, enough for 4-8 attacks', '+1 to entangle and trip with the hook and cable', 'Assault and defense, secondarily anti-personnel. For climbing, swinging around walls and obstacles and snaring opponents; instead of firing it, the fighter can pay out 6-12 ft (1.8 to 3.7 m) of line to trip legs or tangle an arm or leg. An arena favorite. 12,000 credits (gear row ng-gccpa-03-forearm-grappling-hook).'),
  ('ng-gccpa-03-pit-fighter', 8, 'Forearm Vibro-Short Sword', '2D4 M.D.', 1, 'Melee only; arm''s reach plus a blade of 1-2 ft (0.3 to 0.6 m) past the fist', 'Equal to the pilot''s combined hand to hand attacks', NULL, NULL, 'Assault, secondarily defense. Retractable, built into one forearm. 10,000 credits (gear row ng-gccpa-03-forearm-vibro-short-sword).'),
  ('ng-gccpa-03-pit-fighter', 9, 'Forearm Vibro-Claws', '2D4+3 M.D.', 1, 'Melee only; arm''s reach', 'Equal to the pilot''s combined hand to hand attacks', NULL, NULL, 'Assault, secondarily defense. Three curved claws, or three long narrow blades, that extend and retract from one forearm. 12,000 credits (gear row ng-gccpa-03-forearm-vibro-claws).'),
  ('ng-gccpa-03-pit-fighter', 10, 'Vibro-Spikes or Blades (per set)', '1D6 M.D. for a set of four small Vibro-Spikes; 2D4 M.D. for a set of two dagger-size blades or bigger spikes', 1, 'Melee only', 'Equal to the pilot''s combined hand to hand attacks', NULL, NULL, 'Assault, secondarily defense. Four spikes or two blades on a shin, knee, heel, forearm back, elbow or shoulder top, for looks or to slam and impale. 10,000 credits a set, each location needing its own (gear row ng-gccpa-03-vibro-spikes-or-blades).'),
  ('ng-gccpa-03-pit-fighter', 11, 'Whipping Cables (2)', '1D4 M.D. per lash, or entangle and tie up the opponent; energized cables 1D6+2 M.D. a lash, sparking at each hit', 1, 'Melee only; 15 ft (4.6 m) long', 'Equal to the pilot''s combined hand to hand attacks', NULL, '+1 to strike, +1 to disarm and +2 to entangle', 'Anti-personnel, secondarily defense. A pair extending from housings under the forearms. 6,500 credits standard, 12,500 energized (gear rows ng-gccpa-03-whipping-cables and ng-gccpa-03-energized-whipping-cables).'),
  ('ng-gccpa-03-pit-fighter', 12, 'Concealed Net Launcher (1, shoulder)', 'None; it immobilizes. A failed dodge leaves the victim wrapped in the net and down to one melee action per round until cut loose: 3D6+20 M.D. to the netting, fire doing double and burning the net away in one round while also burning whoever is inside', 0, '100 ft (30.5 m)', 'Each net counts as one melee attack', '4 nets', NULL, 'Capture, secondarily anti-personnel and defense. Fires a bundle of glue-coated M.D.C. mesh that bursts open and wraps the target, weighted cords sticking to one another. It holds Robot P.S. 24 (Supernatural 18) or less; stronger foes break out in 1D4 melee actions, and above Robot P.S. 32 (Supernatural 24) in one. Cutting free from inside also takes 1D4+1 melee actions, and a net wrapped round the lower legs needs 3 more P.S. to break. Also made as a bazooka-like handheld launcher. Shoulder mount 27,000 credits, handheld 32,000, replacement nets 3,500 each (gear rows ng-gccpa-03-shoulder-net-launcher, ng-gccpa-03-handheld-net-launcher and ng-gccpa-03-replacement-net).'),
  ('ng-gccpa-03-pit-fighter', 13, 'Giant Two-Handed Vibro-Chainsaw Sword (optional)', '5D6+5 M.D. per strike', 1, 'Melee; 5 ft (1.5 m) beyond arm''s reach, 7 ft (2.1 m) overall', 'Equal to the pilot''s combined hand to hand attacks', '30 minutes per E-Clip in the hilt; unlimited on a UEL', '+1 to parry and disarm', 'Assault, secondarily anti-armor, anti-robot and anti-monster. Made first for Combat Cyborgs and a crowd-pleaser in the pits: a 5 ft (1.5 m) chainsaw blade on a 2 ft (0.6 m) handle, 50 lbs (22.5 kg). Needs Robot P.S. 19 two-handed and 25 one-handed; weaker users are -5 to strike and parry, and below Robot P.S. 16 -10 to strike, parry and disarm. 55,000 credits (gear row ng-gccpa-03-vibro-chainsaw-sword).'),
  ('ng-x67-prophet', 1, 'Forearm Laser (1, right)', 'Three settings: 6D6x10 S.D.C., 1D6 M.D. or 2D6 M.D.', 1, '1,200 ft (366 m)', 'Each blast counts as one melee attack', 'Effectively unlimited on nuclear and Solid Oxide suits; 20 full-power blasts per E-Clip on the battery version', NULL, 'Anti-personnel, secondarily defense. A low-profile, short-range point-and-shoot laser.'),
  ('ng-x67-prophet', 2, 'Forearm Ion Weapon (1, left)', 'Two settings: 2D6 M.D. or 4D6 M.D.', 1, '1,000 ft (305 m)', 'Each blast counts as one melee attack', 'Effectively unlimited on nuclear and Solid Oxide suits; 20 full-power blasts per E-Clip on the battery version', NULL, 'Anti-personnel, secondarily defense. A low-profile, short-range point-and-shoot ion blaster.'),
  ('ng-x67-prophet', 3, 'Forearm Vibro-Blades (2)', '1D6 M.D.', 1, 'Arm''s reach; melee', 'Each attack counts as one melee action', 'Effectively unlimited', NULL, 'Assault and anti-monster, secondarily defense and sabotage. One concealed, extendible blade per forearm for prying doors open, cutting locks and debris and close combat. Silver plating against the supernatural is 2,500 credits a blade (gear row ng-x67-prophet-silver-plating).');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 4 machines are in' AS assertion, count(*) AS got, 4 AS want
  FROM vehicles WHERE slug IN ('ng-x16-midas', 'ng-uelx45-night-reaper', 'ng-gccpa-03-pit-fighter', 'ng-x67-prophet');
SELECT 'their 38 locations are in' AS assertion, count(*) AS got, 38 AS want
  FROM vehicle_locations WHERE vehicle_slug IN ('ng-x16-midas', 'ng-uelx45-night-reaper', 'ng-gccpa-03-pit-fighter', 'ng-x67-prophet');
SELECT 'their 22 weapon entries are in' AS assertion, count(*) AS got, 22 AS want
  FROM vehicle_weapons WHERE vehicle_slug IN ('ng-x16-midas', 'ng-uelx45-night-reaper', 'ng-gccpa-03-pit-fighter', 'ng-x67-prophet');
SELECT 'each main body location equals mdc_main_body' AS assertion, count(*) AS got, 0 AS want
  FROM vehicles v JOIN vehicle_locations l ON l.vehicle_slug = v.slug AND l.location = 'Main Body'
  WHERE v.slug IN ('ng-x16-midas', 'ng-uelx45-night-reaper', 'ng-gccpa-03-pit-fighter', 'ng-x67-prophet') AND l.mdc IS NOT NULL AND v.mdc_main_body IS NOT NULL AND l.mdc <> v.mdc_main_body;

